// ตรวจสอบเงื่อนไข 2 ข้อ:
// 1. มี Reply จาก email_id ที่ Flow Auto mail บันทึกเอาไว้ (เช็คจาก In-Reply-To / References)
// 2. มี Email ส่งมาหาโดย Mail header (subject) มี Prefix ตามที่กำหนดไว้

const item = $input.item.json;
const subject = item.subject || '';
const inReplyTo = item.headers?.['in-reply-to'] || '';
const references = item.headers?.references || '';

// ดึงรายการ Prefix จาก Config
let prefixes = ['[แจ้งเตือนครบกำหนด]', '[URGENT]', '[CONTRACT]'];
try {
  const configPrefixes = $('Global Forward Config').item.json.subject_prefixes;
  if (configPrefixes) {
    prefixes = configPrefixes.split(',').map(p => p.trim().toLowerCase());
  }
} catch (e) {}

// ตรวจสอบเงื่อนไข 1: เป็น Reply ของ email_id หรือไม่
// (เช็คว่ามี in-reply-to/references หรือ subject มี Re:)
const isReplyEmail = Boolean(
  inReplyTo || 
  references || 
  subject.toLowerCase().startsWith('re:')
);

// ตรวจสอบเงื่อนไข 2: Subject มี Prefix ที่กำหนดหรือไม่
const lowerSubject = subject.toLowerCase();
const matchedPrefix = prefixes.find(p => p && lowerSubject.includes(p.toLowerCase()));
const hasSubjectPrefix = Boolean(matchedPrefix);

// สรุปว่าเข้าเงื่อนไขหรือไม่
if (isReplyEmail || hasSubjectPrefix) {
  let reason = '';
  if (isReplyEmail && hasSubjectPrefix) {
    reason = `Reply from tracked email_id AND Matched Prefix "${matchedPrefix}"`;
  } else if (isReplyEmail) {
    reason = `Reply from tracked email_id (${inReplyTo || references || 'Re: subject'})`;
  } else {
    reason = `Matched Subject Prefix: "${matchedPrefix}"`;
  }

  return {
    json: {
      ...item,
      is_matched: true,
      matched_reason: reason,
      in_reply_to_id: inReplyTo,
      references_id: references
    }
  };
}

// ไม่เข้าเงื่อนไข ไม่ต้องทำอะไรต่อ
return [];

// 1. นำ Email ที่อยู่ในเงื่อนไขทำการ Forward ไปที่ email เป้าหมาย
const mail = $input.item.json;

const originalFrom = mail.from?.text || mail.from?.value?.[0]?.address || mail.from || 'Unknown Sender';
const originalSubject = mail.subject || 'No Subject';
const originalDate = mail.date || new Date().toISOString();
const originalBody = mail.html || `<pre style="white-space: pre-wrap; font-family: inherit;">${mail.text || '(ไม่มีข้อความ)'}</pre>`;
const reason = mail.matched_reason || 'Matched Criteria';

const targetEmail = $('Global Forward Config').item.json.target_forward_email || 'target-team@yourdomain.com';
const forwardSubject = originalSubject.toLowerCase().startsWith('fwd:') ? originalSubject : `Fwd: ${originalSubject}`;

const forwardHtml = `
<div style="font-family: Arial, sans-serif; font-size: 14px; line-height: 1.6; color: #222;">
  <div style="background-color: #e8f0fe; border-left: 4px solid #1a73e8; padding: 12px 16px; margin-bottom: 20px;">
    <strong>🚀 [Auto-Forwarded by n8n Listener]</strong><br/>
    <span>เงื่อนไขที่ตรวจพบ: <code>${reason}</code></span>
  </div>

  <div style="background-color: #f8f9fa; border: 1px solid #ddd; padding: 12px 16px; margin-bottom: 20px; font-size: 13px;">
    <p style="margin: 2px 0;"><strong>From:</strong> ${originalFrom}</p>
    <p style="margin: 2px 0;"><strong>Date:</strong> ${originalDate}</p>
    <p style="margin: 2px 0;"><strong>Subject:</strong> ${originalSubject}</p>
    ${mail.in_reply_to_id ? `<p style="margin: 2px 0;"><strong>In-Reply-To (email_id):</strong> ${mail.in_reply_to_id}</p>` : ''}
  </div>

  <div style="margin-top: 20px;">
    ${originalBody}
  </div>
</div>
`;

return {
  json: {
    forward_to: targetEmail,
    forward_subject: forwardSubject,
    forward_html: forwardHtml,
    original_from: originalFrom,
    original_subject: originalSubject,
    matched_reason: reason
  }
};
